#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include "mmt_lib.h"
#define H2_RULE_ID "98"
/*
 * HTTP/2 frame reader over the TCP payload of each packet.
 *
 * mmt-dpi gives the packet's TCP segment, not HTTP/2 frames: a frame can
 * span segments and a segment can hold several frames. The state of each
 * direction of a connection keeps the next TCP sequence number, and the
 * bytes of an incomplete frame, so every frame is handled once and whole:
 * - a retransmitted segment is ignored;
 * - after a gap (lost segment), or when the capture starts in the middle of
 *   a connection, the reader resynchronises on a segment that starts with a
 *   plausible frame header;
 * - a segment that starts with the connection preface starts a new
 *   connection on the same 4-tuple (it has a new ISN), and the state of both
 *   directions restarts, only once the old connection is over: its sender
 *   ended it (a FIN after its last byte, or an RST at the expected sequence
 *   number), or the peer accepted a new connection (a SYN-ACK), whose first
 *   byte is the preface. Any other preface is read as a segment of the
 *   current connection: data at the expected sequence number (e.g., the end
 *   of a DATA frame), or a segment the receiver drops (a retransmission, a
 *   segment out of its window), which a sender could otherwise use to wipe
 *   the state. A SYN alone does not end a connection: the receiver of a SYN
 *   on an established connection answers with an ACK (RFC 5961, 4.2). So
 *   the rule reads the TCP flags of every TCP packet, also without data, of
 *   the connections it tracks;
 * - a sequence number more than H2_MAX_BACKWARD bytes behind the expected one
 *   starts a new byte stream (the frame reader resynchronises).
 *
 * Both directions of a connection share one entry of a table of sets of
 * H2_WAYS entries, so they never evict each other. The table holds
 * MMT_SEC_HTTP2_CONNECTIONS connections (environment variable, 128 by
 * default, rounded up to a multiple of H2_WAYS). The set is a hash of the
 * 4-tuple with a random seed, so a sender cannot choose a 4-tuple that
 * collides with another connection. MMT_SEC_HTTP2_SEED (environment
 * variable) fixes the seed: for tests only, as it makes the sets
 * predictable. A new connection replaces the least
 * recently used entry of its set. Each mmt-security thread has its own
 * table (thread-local, never shared); every table is in a list, so that
 * on_unload frees the tables of every thread.
 *
 * Frames larger than the default SETTINGS_MAX_FRAME_SIZE (16384 bytes) are
 * skipped: a peer that advertises a larger maximum can send bigger frames,
 * which are not read.
 */
#include <stdint.h>
#include <strings.h>
#include <pthread.h>
#include <time.h>
#include <sys/random.h>
#include <errno.h>
#include <inttypes.h>
#include <mmt_core.h>

#define H2_WAYS          4                //connections per set of the connection table of a thread
#define H2_CONNECTIONS   128              //default connections per thread (env. MMT_SEC_HTTP2_CONNECTIONS)
#define H2_MAX_CONNECTIONS 65536
#define H2_MAX_FRAME     16384            //default SETTINGS_MAX_FRAME_SIZE (RFC 9113, 6.5.2)
#define H2_BUF_MAX       (H2_MAX_FRAME + 9)
#define H2_MAX_BACKWARD  (1u << 20)       //a sequence number this far behind starts a new byte stream

#define H2_PROTO_HTTP2   700              //PROTO_HTTP2 of mmt-dpi (tcpip/mmt_tcpip_protocols.h)
#define H2_TCP_FIN       0x01
#define H2_TCP_SYN       0x02
#define H2_TCP_RST       0x04
#define H2_TCP_ACK       0x10

static const char H2_PREFACE[] = "PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n";

//fields of the state of one direction of a connection, shared by the rules
#define H2_DIR_COMMON_FIELDS \
	bool     synced;      /*next_seq is known*/                  \
	uint32_t next_seq;                                           \
	bool     aligned;     /*the next byte starts a frame*/       \
	uint32_t skip;        /*bytes left of a frame not buffered*/ \
	uint8_t *buf;         /*incomplete frame*/                   \
	uint32_t buf_len;                                            \
	bool     is_client;   /*sent the preface or a request*/      \
	bool     preface_seen;                                       \
	uint32_t preface_seq; /*sequence number of the preface*/     \
	bool     ended;       /*FIN or RST of the sender at next_seq*/ \
	bool     syn_acked;   /*a SYN-ACK accepted a new connection*/ \
	uint32_t syn_next;    /*its first sequence number*/


#define H2_OPEN_STREAMS 16

struct h2_dir_struct{
	H2_DIR_COMMON_FIELDS
	//request bodies received in several DATA frames: stream id, and whether the body is JSON
	uint32_t open_sid[ H2_OPEN_STREAMS ];
	bool     open_json[ H2_OPEN_STREAMS ];
	uint32_t open_next;
};

typedef struct h2_dir_struct h2_dir_t;

//one connection: both directions
typedef struct h2_conn_struct{
	bool     used;
	uint8_t  key[12];    //the two endpoints (IPv4 address, port), the lower one first
	uint64_t last_use;
	h2_dir_t dir[2];     //dir[0]: sent by the first endpoint of #key, dir[1]: by the second
}h2_conn_t;

//the connections of one thread
typedef struct h2_table_struct{
	struct h2_table_struct *next;   //list of the tables of every thread
	uint64_t  seed, clock;
	uint32_t  sets;
	h2_conn_t conn[];               //sets * H2_WAYS connections
}h2_table_t;

//rule-specific: called for each complete frame
static int h2_on_frame( h2_dir_t *d, uint8_t type, uint8_t flags, uint32_t sid, const uint8_t *p, uint32_t len );
//rule-specific: called when the byte stream of #d is lost (gap), or #d is reset
static void h2_on_desync( h2_dir_t *d );
static void h2_on_reset( h2_dir_t *d );

static __thread h2_table_t *h2_table = NULL;
static h2_table_t *h2_tables = NULL;
static pthread_mutex_t h2_tables_lock = PTHREAD_MUTEX_INITIALIZER;
//set by on_load, before any packet is read
static uint32_t h2_sets = H2_CONNECTIONS / H2_WAYS;
static bool     h2_seed_fixed = false;
static uint64_t h2_seed;

/**
 * Read the environment variable #name as a decimal integer in [#min, #max].
 * Return false if it is not set, or, with a warning, if it is not valid.
 */
static inline bool h2_env_uint( const char *name, uint64_t min, uint64_t max, uint64_t *v ){
	const char *str = getenv( name );
	char *end;
	unsigned long long x;
	if( str == NULL )
		return false;
	errno = 0;
	x = strtoull( str, &end, 10 );
	if( !isdigit( (unsigned char)str[0] ) || *end != '\0' || errno != 0 || x < min || x > max ){
		mmt_warn( "Rule %s: ignore %s=\"%s\": not an integer from %"PRIu64" to %"PRIu64", use the default",
				H2_RULE_ID, name, str, min, max );
		return false;
	}
	*v = x;
	return true;
}

//the environment variables of the connection table; called by on_load
static inline void h2_load_env( void ){
	uint64_t v;
	if( h2_env_uint( "MMT_SEC_HTTP2_CONNECTIONS", 1, H2_MAX_CONNECTIONS, &v )){
		h2_sets = (uint32_t)((v + H2_WAYS - 1) / H2_WAYS);
		mmt_info( "Rule %s: set MMT_SEC_HTTP2_CONNECTIONS=%"PRIu64": %u connections per thread",
				H2_RULE_ID, v, h2_sets * H2_WAYS );
	}
	if( h2_env_uint( "MMT_SEC_HTTP2_SEED", 0, UINT64_MAX, &v )){
		h2_seed_fixed = true;
		h2_seed       = v;
		mmt_warn( "Rule %s: MMT_SEC_HTTP2_SEED is set: the connection table is predictable (for tests only)", H2_RULE_ID );
	}
}

static inline uint32_t h2_u24( const uint8_t *p ){
	return ((uint32_t)p[0] << 16) | ((uint32_t)p[1] << 8) | p[2];
}
static inline uint32_t h2_u32( const uint8_t *p ){
	return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3];
}

//whether #p (at least 9 bytes) looks like a frame header: used only to resynchronise
static inline bool h2_plausible_header( const uint8_t *p ){
	return h2_u24( p ) <= H2_MAX_FRAME && p[3] <= 0x09 && (p[5] & 0x80) == 0;
}

static inline void h2_reset( h2_dir_t *d ){
	h2_on_reset( d );
	free( d->buf );
	memset( d, 0, sizeof( *d ));
}

static inline void h2_reset_conn( h2_conn_t *c ){
	h2_reset( &c->dir[0] );
	h2_reset( &c->dir[1] );
	c->used = false;
}

static inline uint64_t h2_new_seed( const void *addr ){
	uint64_t seed = 0;
	struct timespec ts;
	if( h2_seed_fixed )
		return h2_seed;
	if( getrandom( &seed, sizeof( seed ), GRND_NONBLOCK ) != (ssize_t)sizeof( seed )){
		clock_gettime( CLOCK_REALTIME, &ts );
		seed = ((uint64_t)ts.tv_sec << 32) ^ (uint64_t)ts.tv_nsec ^ (uint64_t)(uintptr_t)addr;
	}
	return seed;
}

//set of the connection #key: seeded FNV-1a, then the MurmurHash3 finaliser so that every bit counts
static inline uint32_t h2_set_of( const h2_table_t *t, const uint8_t *key ){
	uint64_t h = 14695981039346656037ull ^ t->seed;
	int i;
	for( i=0; i<12; i++ )
		h = (h ^ key[i]) * 1099511628211ull;
	h ^= h >> 33;
	h *= 0xff51afd7ed558ccdull;
	h ^= h >> 33;
	h *= 0xc4ceb9fe1a85ec53ull;
	h ^= h >> 33;
	return (uint32_t)(h % t->sets);
}

static inline h2_table_t *h2_get_table( void ){
	h2_table_t *t = h2_table;
	if( t != NULL )
		return t;
	t = calloc( 1, sizeof( h2_table_t ) + (size_t)h2_sets * H2_WAYS * sizeof( h2_conn_t ));
	if( t == NULL )
		return NULL;
	t->sets = h2_sets;
	t->seed = h2_new_seed( t );
	pthread_mutex_lock( &h2_tables_lock );
	t->next   = h2_tables;
	h2_tables = t;
	pthread_mutex_unlock( &h2_tables_lock );
	h2_table = t;
	return t;
}

/**
 * The state of the direction src:sport -> dst:dport, and in #reverse the
 * state of the opposite direction of the same connection. If the connection
 * is not tracked: a new entry if #create, else NULL.
 */
static inline h2_dir_t *h2_get_dir( const void *src, const void *dst, double sport, double dport, h2_dir_t **reverse, bool create ){
	uint8_t a[6], b[6], key[12];
	int side, i;
	h2_conn_t *set, *c, *victim = NULL;
	h2_table_t *t = h2_get_table();

	if( t == NULL )
		return NULL;
	memcpy( a, src, 4 );
	a[4] = ((uint32_t)sport) >> 8; a[5] = ((uint32_t)sport) & 0xFF;
	memcpy( b, dst, 4 );
	b[4] = ((uint32_t)dport) >> 8; b[5] = ((uint32_t)dport) & 0xFF;
	side = ( memcmp( a, b, 6 ) > 0 ); //1: the source is the second endpoint
	memcpy( key,     side ? b : a, 6 );
	memcpy( key + 6, side ? a : b, 6 );

	set = &t->conn[ h2_set_of( t, key ) * H2_WAYS ];
	for( i=0; i<H2_WAYS; i++ ){
		c = &set[i];
		if( c->used && memcmp( c->key, key, 12 ) == 0 )
			goto found;
		//a free entry, else the least recently used one
		if( victim == NULL || (victim->used && (!c->used || c->last_use < victim->last_use)) )
			victim = c;
	}
	if( !create )
		return NULL;
	c = victim;
	h2_reset_conn( c );
	memcpy( c->key, key, 12 );
	c->used = true;

	found:
	c->last_use = ++ t->clock;
	if( reverse != NULL )
		*reverse = &c->dir[ !side ];
	return &c->dir[ side ];
}

static inline void h2_desync( h2_dir_t *d ){
	d->aligned = false;
	d->skip    = 0;
	d->buf_len = 0;
	h2_on_desync( d );
}

//handle the complete frame at #p (9-byte header + payload); return its rule-specific result
static inline int h2_frame( h2_dir_t *d, const uint8_t *p ){
	return h2_on_frame( d, p[3], p[4], h2_u32( p + 5 ) & 0x7FFFFFFF, p + 9, h2_u24( p ));
}

//append #n bytes to the incomplete frame of #d
static inline bool h2_buffer( h2_dir_t *d, const uint8_t *p, size_t n ){
	if( d->buf == NULL ){
		d->buf = malloc( H2_BUF_MAX );
		if( d->buf == NULL )
			return false;
	}
	memcpy( d->buf + d->buf_len, p, n );
	d->buf_len += n;
	return true;
}

/**
 * Whether a segment of direction #d that starts with the connection preface
 * at #seq starts a new connection on the 4-tuple.
 */
static inline bool h2_new_connection( const h2_dir_t *d, uint32_t seq ){
	if( !d->synced )                              //first segment of this direction
		return true;
	if( d->preface_seen && seq == d->preface_seq ) //retransmission of the preface already read
		return false;
	return d->ended                               //the old connection is over
		|| (d->syn_acked && seq == d->syn_next);  //first byte of the new connection
}

/**
 * Feed the TCP segment (#seq, #p, #len) of direction #d to the frame reader;
 * #rev is the opposite direction (or NULL).
 * Return 1 if a frame of the segment made #h2_on_frame return 1.
 */
static inline int h2_segment( h2_dir_t *d, h2_dir_t *rev, uint32_t seq, const uint8_t *p, size_t len ){
	int ret = 0;
	uint32_t flen, n, total;

	if( len >= 24 && memcmp( p, H2_PREFACE, 24 ) == 0 && h2_new_connection( d, seq )){
		//a new connection on this 4-tuple: both directions restart
		h2_reset( d );
		if( rev != NULL && rev != d )
			h2_reset( rev );
		d->preface_seen = true;
		d->preface_seq  = seq;
		d->is_client    = true;
		d->aligned      = true;
		p   += 24;
		len -= 24;
		seq += 24;
	}else if( d->synced ){
		int32_t diff = (int32_t)(seq - d->next_seq);
		if( diff < 0 && (uint32_t)(-(int64_t)diff) > H2_MAX_BACKWARD )
			h2_desync( d ); //far behind: a new byte stream, not a retransmission
		else if( diff < 0 ){ //retransmission, possibly overlapping new data
			if( (size_t)(-(int64_t)diff) >= len )
				return 0;
			p   += -diff;
			len -= -diff;
			seq  = d->next_seq;
		}else if( diff > 0 ) //gap: bytes were lost
			h2_desync( d );
	}
	d->synced   = true;
	d->next_seq = seq + (uint32_t)len;

	while( len > 0 ){
		//rest of a frame too large to be buffered
		if( d->skip > 0 ){
			n = ( d->skip < len ) ? d->skip : (uint32_t)len;
			d->skip -= n;
			p   += n;
			len -= n;
			continue;
		}
		//incomplete frame from the previous segments
		if( d->buf_len > 0 ){
			if( d->buf_len < 9 ){
				n = 9 - d->buf_len;
				n = ( n < len ) ? n : (uint32_t)len;
				h2_buffer( d, p, n );
				p   += n;
				len -= n;
				if( d->buf_len < 9 )
					return ret;
			}
			total = 9 + h2_u24( d->buf );
			if( total > H2_BUF_MAX ){
				d->skip    = total - d->buf_len;
				d->buf_len = 0;
				continue;
			}
			n = total - d->buf_len;
			n = ( n < len ) ? n : (uint32_t)len;
			h2_buffer( d, p, n );
			p   += n;
			len -= n;
			if( d->buf_len < total )
				return ret;
			d->buf_len = 0;
			ret |= h2_frame( d, d->buf );
			continue;
		}
		//frame starting in this segment
		if( !d->aligned ){
			if( len < 9 || !h2_plausible_header( p ))
				return ret; //wait for a segment starting with a frame
			d->aligned = true;
		}
		if( len < 9 ){
			if( !h2_buffer( d, p, len ))
				h2_desync( d );
			return ret;
		}
		flen = h2_u24( p );
		if( 9 + (size_t)flen <= len ){
			ret |= h2_frame( d, p );
			p   += 9 + flen;
			len -= 9 + flen;
			continue;
		}
		if( 9 + flen > H2_BUF_MAX ){
			d->skip = 9 + flen - (uint32_t)len;
			return ret;
		}
		if( !h2_buffer( d, p, len ))
			h2_desync( d );
		return ret;
	}
	return ret;
}

/**
 * Feed the TCP packet (#seq, #ack, #flags, and #len bytes of data at #p,
 * #len can be 0) of direction #d; #rev is the opposite direction (or NULL).
 * The flags tell when a connection is over (h2_new_connection).
 * Return 1 if a frame of the segment made #h2_on_frame return 1.
 */
static inline int h2_packet( h2_dir_t *d, h2_dir_t *rev, uint32_t seq, uint32_t ack, uint8_t flags, const uint8_t *p, size_t len ){
	int ret = 0;

	if( flags & H2_TCP_RST ){
		//the receiver ignores an RST that is not at the expected sequence number (RFC 5961, 3.2)
		if( d->synced && seq == d->next_seq )
			d->ended = true;
		return 0; //the data of an RST is not data of the stream
	}
	if( flags & H2_TCP_SYN ){
		if( (flags & H2_TCP_ACK) && rev != NULL ){
			//the sender accepted a new connection, whose data starts at #ack
			rev->syn_acked = true;
			rev->syn_next  = ack;
		}
		seq ++; //data in a SYN (TCP Fast Open) starts after it
	}
	if( len > 0 )
		ret = h2_segment( d, rev, seq, p, len );
	//FIN after the last byte of the stream (not of a retransmission behind it, not out of the window)
	if( (flags & H2_TCP_FIN) && d->synced && seq + (uint32_t)len == d->next_seq )
		d->ended = true;
	return ret;
}

//whether the protocol hierarchy (meta.proto_hierarchy) of a packet holds HTTP/2
static inline bool h2_in_hierarchy( const void *hierarchy ){
	const proto_hierarchy_t *h = (const proto_hierarchy_t *)hierarchy;
	int i;
	if( h == NULL )
		return false;
	for( i=0; i<h->len && i<PROTO_PATH_SIZE; i++ )
		if( h->proto_path[i] == H2_PROTO_HTTP2 )
			return true;
	return false;
}

/**
 * The state of the direction of a TCP packet, or NULL if the rule has nothing
 * to do with it: a packet with data, of HTTP/2, creates the state of its
 * connection; a SYN, FIN or RST without data matters only to a connection
 * already tracked; other packets are ignored. #len is set to the data length.
 */
static inline h2_dir_t *h2_packet_dir( const void *src, const void *dst, double sport, double dport, double flags,
		const char *payload, const void *hierarchy, h2_dir_t **reverse, size_t *len ){
	bool h2 = ( payload != NULL && h2_in_hierarchy( hierarchy ));
	*len = 0;
	if( src == NULL || dst == NULL )
		return NULL;
	if( !h2 && (payload != NULL || ((uint32_t)flags & (H2_TCP_SYN | H2_TCP_FIN | H2_TCP_RST)) == 0) )
		return NULL;
	if( h2 )
		*len = mmt_mem_size( payload );
	return h2_get_dir( src, dst, sport, dport, reverse, h2 );
}

//free the connection tables of every thread
static inline void h2_free_tables( void ){
	h2_table_t *t, *next;
	uint32_t i;
	pthread_mutex_lock( &h2_tables_lock );
	for( t = h2_tables; t != NULL; t = next ){
		next = t->next;
		for( i=0; i<t->sets * H2_WAYS; i++ )
			h2_reset_conn( &t->conn[i] );
		free( t );
	}
	h2_tables = NULL;
	pthread_mutex_unlock( &h2_tables_lock );
	h2_table = NULL;
}

//payload of a HEADERS (type 1) or PUSH_PROMISE (type 5) frame without padding, priority and promised stream id
static inline bool h2_header_block( uint8_t type, uint8_t flags, const uint8_t **p, uint32_t *len ){
	uint32_t pad = 0;
	if( flags & 0x08 ){ //PADDED
		if( *len < 1 ) return false;
		pad = (*p)[0];
		(*p) ++; (*len) --;
	}
	if( type == 1 && (flags & 0x20) ){ //PRIORITY
		if( *len < 5 ) return false;
		(*p) += 5; (*len) -= 5;
	}
	if( type == 5 ){ //promised stream id
		if( *len < 4 ) return false;
		(*p) += 4; (*len) -= 4;
	}
	if( pad > *len ) return false;
	*len -= pad;
	return true;
}

//HPACK integer with a #prefix-bit prefix (RFC 7541, 5.1); return false if malformed
static inline bool hpack_int( const uint8_t **p, const uint8_t *end, int prefix, uint32_t *v ){
	uint32_t m = (1u << prefix) - 1, shift = 0;
	uint8_t b;
	if( *p >= end ) return false;
	*v = (*(*p)++) & m;
	if( *v < m ) return true;
	do{
		if( *p >= end || shift > 21 ) return false;
		b = *(*p)++;
		*v += (uint32_t)(b & 0x7F) << shift;
		shift += 7;
	}while( b & 0x80 );
	return true;
}

static void h2_on_reset( h2_dir_t *d ){ }
static void h2_on_desync( h2_dir_t *d ){
	memset( d->open_sid, 0, sizeof( d->open_sid ));
}

//index of stream #sid in the open bodies of #d, or -1
static inline int h2_open_find( const h2_dir_t *d, uint32_t sid ){
	int i;
	for( i=0; i<H2_OPEN_STREAMS; i++ )
		if( d->open_sid[i] == sid )
			return i;
	return -1;
}

/*
 * Strict JSON syntax check (RFC 8259), without recursion: any nesting depth
 * is accepted. Newline-delimited JSON (JSON texts separated by a line break,
 * e.g., a bulk request) is accepted too.
 */
static inline void json_ws( const uint8_t **p, const uint8_t *end ){
	while( *p < end && (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r') )
		(*p) ++;
}

static inline bool json_string( const uint8_t **p, const uint8_t *end ){
	const uint8_t *c = *p + 1; //after '"'
	int i;
	while( c < end ){
		if( *c == '"' ){
			*p = c + 1;
			return true;
		}
		if( *c < 0x20 )
			return false;
		if( *c == '\\' ){
			c ++;
			if( c >= end )
				return false;
			if( *c == 'u' ){
				for( i=1; i<=4; i++ )
					if( c + i >= end || !isxdigit( c[i] ))
						return false;
				c += 4;
			}else if( strchr( "\"\\/bfnrt", *c ) == NULL || *c == '\0' )
				return false;
		}
		c ++;
	}
	return false;
}

static inline bool json_number( const uint8_t **p, const uint8_t *end ){
	const uint8_t *c = *p;
	if( c < end && *c == '-' ) c++;
	if( c >= end ) return false;
	if( *c == '0' ) c++;
	else if( *c >= '1' && *c <= '9' ) while( c < end && isdigit( *c )) c++;
	else return false;
	if( c < end && *c == '.' ){
		c++;
		if( c >= end || !isdigit( *c )) return false;
		while( c < end && isdigit( *c )) c++;
	}
	if( c < end && (*c == 'e' || *c == 'E') ){
		c++;
		if( c < end && (*c == '+' || *c == '-') ) c++;
		if( c >= end || !isdigit( *c )) return false;
		while( c < end && isdigit( *c )) c++;
	}
	*p = c;
	return true;
}

static inline bool json_literal( const uint8_t **p, const uint8_t *end, const char *lit ){
	size_t n = strlen( lit );
	if( (size_t)(end - *p) < n || memcmp( *p, lit, n ) != 0 )
		return false;
	*p += n;
	return true;
}

//a member name and its ':'
static inline bool json_key( const uint8_t **p, const uint8_t *end ){
	json_ws( p, end );
	if( *p >= end || **p != '"' || !json_string( p, end ))
		return false;
	json_ws( p, end );
	if( *p >= end || **p != ':' )
		return false;
	(*p) ++;
	return true;
}

//scalar value: string, number, true, false, null
static inline bool json_scalar( const uint8_t **p, const uint8_t *end ){
	switch( **p ){
	case '"': return json_string( p, end );
	case 't': return json_literal( p, end, "true" );
	case 'f': return json_literal( p, end, "false" );
	case 'n': return json_literal( p, end, "null" );
	default:  return json_number( p, end );
	}
}

static inline bool json_is_valid( const uint8_t *p, uint32_t len ){
	const uint8_t *end = p + len;
	//kinds of the open containers: bit i is 1 if the container at depth i is an object
	uint8_t small[ 256 ], *kinds = small;
	uint32_t depth = 0, top;
	bool after = false, ok = false, nl;

	//the depth is at most #len: one byte per container
	if( len / 8 + 1 > sizeof( small )){
		kinds = malloc( len / 8 + 1 );
		if( kinds == NULL )
			return true; //cannot check: no alert
	}
	while( true ){
		if( after && depth == 0 ){
			//end of a JSON text: end of the body, or a next JSON text after a line break
			nl = false;
			while( p < end && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') ){
				if( *p == '\n' )
					nl = true;
				p ++;
			}
			if( p == end ){
				ok = true;
				break;
			}
			if( !nl )
				break;
			after = false;
		}
		json_ws( &p, end );
		if( p >= end )
			break;
		if( after ){
			//after a value inside a container: ',' or the end of the container
			top = depth - 1;
			bool is_object = (kinds[ top / 8 ] >> (top % 8)) & 1;
			if( *p == ',' ){
				p ++;
				if( is_object && !json_key( &p, end ))
					break;
				after = false;
			}else if( *p == (is_object ? '}' : ']') ){
				p ++;
				depth --;
			}else
				break;
			continue;
		}
		//a value
		if( *p == '{' || *p == '[' ){
			bool is_object = ( *p == '{' );
			if( is_object )
				kinds[ depth / 8 ] |=  (uint8_t)(1u << (depth % 8));
			else
				kinds[ depth / 8 ] &= (uint8_t)~(1u << (depth % 8));
			depth ++;
			p ++;
			json_ws( &p, end );
			if( p < end && *p == (is_object ? '}' : ']') ){ //empty container
				p ++;
				depth --;
				after = true;
			}else if( is_object && !json_key( &p, end ))
				break;
			continue;
		}
		if( !json_scalar( &p, end ))
			break;
		after = true;
	}
	if( kinds != small )
		free( kinds );
	return ok;
}

static inline bool mem_has( const uint8_t *p, uint32_t len, const char *s ){
	size_t n = strlen( s );
	uint32_t i;
	for( i=0; i+n <= len; i++ )
		if( p[i] == (uint8_t)s[0] && memcmp( p + i, s, n ) == 0 )
			return true;
	return false;
}

//whether the #len bytes at #p start with #s
static inline bool mem_starts( const uint8_t *p, uint32_t len, const char *s ){
	size_t n = strlen( s );
	return ( len >= n && memcmp( p, s, n ) == 0 );
}

//whether a closing backtick follows #i before the end of the JSON string; its index in #close
static inline bool json_backtick_close( const uint8_t *p, uint32_t len, uint32_t i, uint32_t *close ){
	uint32_t k;
	for( k = i + 1; k < len && k < i + 256 && p[k] != '"'; k++ )
		if( p[k] == '`' ){
			*close = k;
			return true;
		}
	return false;
}

static inline int hex_value( uint8_t c ){
	return isdigit( c ) ? c - '0' : tolower( c ) - 'a' + 10;
}

/**
 * Whether the "%XX" at #i, followed by the conversion letter at #j, is a URL
 * escape in URL-encoded text, not a conversion with a width: the escape is a
 * printable character, it follows a letter or a digit that does not end a
 * conversion (#conv_end is the end of the last one), and the letter is
 * followed by another '%' ("Rock%20n%20Roll", "it%20s%20s").
 */
static inline bool url_escape_in_text( const uint8_t *p, uint32_t len, uint32_t i, uint32_t j, uint32_t conv_end ){
	int c = hex_value( p[i+1] ) * 16 + hex_value( p[i+2] );
	return j == i + 3 && j + 1 < len && p[j+1] == '%'
		&& c >= 0x20 && c < 0x7F
		&& i > 0 && isalnum( p[i-1] ) && i != conv_end;
}

/**
 * Injection and fuzzing patterns in a JSON body. Ordinary text is not
 * reported: '#', '%', '$' or '\' alone ("#ff0000", "10%", "$5", "C:\\Users"),
 * URL escapes ("%3d", "%2d"), a single "../", markdown code ("Use `ls`"),
 * jQuery ("$(document).ready"), printf documentation ("%s has %d items").
 */
static inline bool json_has_injection( const uint8_t *p, uint32_t len ){
	uint32_t i, j, k, q, run = 0, conv_end = 0;
	uint8_t prev;
	bool conv;
	for( i=0; i<len; i++ ){
		switch( p[i] ){
		case '%':
			//conversion: flags, width, precision and length ("%08x", "%-10.2ld"), then the conversion letter p[j]
			j = i + 1;
			while( j < len && (isdigit( p[j] ) || p[j] == '.' || p[j] == '-' || p[j] == 'l' || p[j] == 'h' ))
				j++;
			//NUL "%00", also before a conversion letter ("%00x")
			if( i + 2 < len && p[i+1] == '0' && p[i+2] == '0' )
				return true;
			//URL escape "%XX", unless it starts a "%s", "%x", "%X", "%p" or "%n" conversion with a width
			// ("%08x", "%20s", "%10n") outside URL-encoded text: dots "%2e%2e" are reported, the others
			// are text ("%3d", "%2d": a "%d" conversion cannot be told from a URL escape)
			conv = ( j < len && p[j] != '\0' && strchr( "sxXp", p[j] ) != NULL )
					|| ( j < len && p[j] == 'n' && (j + 1 >= len || !isalpha( p[j+1] )) );
			if( i + 2 < len && isxdigit( p[i+1] ) && isxdigit( p[i+2] )
					&& (!conv || url_escape_in_text( p, len, i, j, conv_end ))){
				if( i + 5 < len && strncasecmp( (const char *)p + i, "%2e%2e", 6 ) == 0 )
					return true;
				break;
			}
			//format string: "%n" (not "100%natural"), or 2 conversions next to each other ("%s%s", "%x.%x", "%p %p")
			if( j >= len )
				break;
			if( p[j] == 'n' && (j + 1 >= len || !isalpha( p[j+1] )) )
				return true;
			if( p[j] != '\0' && strchr( "sxXpd", p[j] ) != NULL ){
				run = ( run > 0 && i <= conv_end + 1 ) ? run + 1 : 1;
				conv_end = j + 1;
				if( run >= 2 )
					return true;
			}
			break;
		case '$': //command substitution "$(cmd)", not jQuery: "$(this).hide()", "$('#id')", "$(\"#id\")"
			if( i + 1 >= len || p[i+1] != '(' )
				break;
			//spaces after '(': "$( document ).ready" (jQuery's documented style)
			for( q = i + 2; q < len && q < i + 64 && p[q] == ' '; q++ )
				;
			if( q < len && (p[q] == '\'' || p[q] == '\\') )
				break;
			for( k = q; k < len && k < i + 256 && p[k] != ')' && p[k] != '"'; k++ )
				;
			//a method call on the jQuery object of this, document or window ("$(document).ready"),
			// not "$(whoami).log"
			if( k < len && p[k] == ')' && k + 1 < len && p[k+1] == '.'
					&& (mem_starts( p + q, k - q, "this" ) || mem_starts( p + q, k - q, "document" )
						|| mem_starts( p + q, k - q, "window" )) )
				break;
			return true;
		case '`': //command substitution "`cmd`": a whole value ("`reboot`") or after a shell operator ("x;`id`")
			prev = ( i > 0 ) ? p[i-1] : '"';
			if( !json_backtick_close( p, len, i, &k ))
				break;
			if( strchr( ";|&(=", prev ) != NULL && prev != '\0' )
				return true;
			if( prev == '"' && k + 1 < len && p[k+1] == '"' )
				return true;
			i = k; //the closing backtick does not open another one
			break;
		case '.': //path traversal: "../../", "..\\..\\" (escaped backslashes), "..%2f", "..%5c"
			if( i + 5 < len && memcmp( p + i, "../../", 6 ) == 0 )
				return true;
			if( i + 7 < len && memcmp( p + i, "..\\\\..\\\\", 8 ) == 0 )
				return true;
			if( i + 4 < len && p[i+1] == '.' && (strncasecmp( (const char *)p + i + 2, "%2f", 3 ) == 0 || strncasecmp( (const char *)p + i + 2, "%5c", 3 ) == 0) )
				return true;
			break;
		}
	}
	//NUL character, escaped
	return mem_has( p, len, "\\u0000" );
}

static int h2_on_frame( h2_dir_t *d, uint8_t type, uint8_t flags, uint32_t sid, const uint8_t *p, uint32_t len ){
	uint32_t index, pad;
	const uint8_t *c, *end;
	bool json, complete;
	int i;

	if( type == 1 && !d->is_client ){
		//a request header block starts with a request pseudo-header (:method, :scheme, :path, :authority)
		if( !h2_header_block( type, flags, &p, &len ) || len == 0 )
			return 0;
		c = p; end = p + len;
		while( c < end && (*c & 0xE0) == 0x20 ) //skip dynamic table size updates
			if( !hpack_int( &c, end, 5, &index ))
				return 0;
		if( c >= end )
			return 0;
		if( *c & 0x80 ){
			if( !hpack_int( &c, end, 7, &index )) return 0;
		}else if( !hpack_int( &c, end, ((*c & 0xC0) == 0x40) ? 6 : 4, &index ))
			return 0;
		if( index >= 1 && index <= 7 )
			d->is_client = true;
		return 0;
	}

	//DATA frames of requests only
	if( type != 0 || !d->is_client || sid == 0 )
		return 0;
	if( flags & 0x08 ){ //PADDED
		if( len < 1 ) return 0;
		pad = p[0];
		p ++; len --;
		if( pad > len ) return 0;
		len -= pad;
	}

	i = h2_open_find( d, sid );
	if( i >= 0 ){
		//continuation of a body
		json     = d->open_json[i];
		complete = false;
		if( flags & 0x01 ) //END_STREAM
			d->open_sid[i] = 0;
	}else{
		//first DATA frame of a body: JSON if it starts with '{' or '['
		c = p; end = p + len;
		json_ws( &c, end );
		json     = ( c < end && (*c == '{' || *c == '[') );
		complete = ( flags & 0x01 );
		if( !complete ){
			i = d->open_next;
			d->open_next = (d->open_next + 1) % H2_OPEN_STREAMS;
			d->open_sid[i]  = sid;
			d->open_json[i] = json;
		}
	}
	if( !json || len == 0 )
		return 0;
	if( json_has_injection( p, len ))
		return 1;
	//a body in one DATA frame must be valid JSON: random bytes break it
	return ( complete && !json_is_valid( p, len ));
}

/**
 * Return 1 if the TCP segment completes a DATA frame of an HTTP/2 request
 * whose JSON body holds an injection pattern or is not valid JSON.
 */
static int em_check_fuzzing( const void *src, const void *dst, double sport, double dport, double seq, double ack,
		double flags, const char *payload, const void *hierarchy ){
	h2_dir_t *d, *rev;
	size_t len;
	d = h2_packet_dir( src, dst, sport, dport, flags, payload, hierarchy, &rev, &len );
	if( d == NULL )
		return 0;
	if( d == rev ) //same source and destination
		rev = NULL;
	return h2_packet( d, rev, (uint32_t)seq, (uint32_t)ack, (uint8_t)flags, (const uint8_t *)payload, len );
}

void on_load(){
	h2_load_env();
}

//called once, by the main thread: free the state of every thread
void on_unload(){
	h2_free_tables();
}
